<template>
  <section class="footer__nav">
    <div class="footer__nav-partition">
      <label class="footer__nav-title" for="to-buyer">{{
        $t('footer.navigation.buyer')
      }}</label>
      <input
        id="to-buyer"
        class="footer__nav-marker"
        name="tabs"
        type="checkbox"
      />
      <div class="footer__nav-list-wrapper">
        <ul class="footer__nav-list" @click="onClose">
          <li class="footer__nav-list-item">
            <nuxt-link
              :to="localePath(`/faq/buyer/`)"
              class="footer__nav-link"
              target="_self"
            >FAQ</nuxt-link>
          </li>
          <li class="footer__nav-list-item">
            <nuxt-link
              :to="{path:localePath(`/faq/buyer`), hash: '#cart'}"
              class="footer__nav-link"
              target="_self"
            >{{ $t('footer.navigation.order') }}
            </nuxt-link>
          </li>
          <li class="footer__nav-list-item">
            <nuxt-link
              :to="{path:localePath(`/faq/buyer`), hash: '#payment'}"
              class="footer__nav-link"
              target="_self">
              {{ $t('footer.navigation.payment') }}
            </nuxt-link>
          </li>
          <li class="footer__nav-list-item">
            <nuxt-link
              :to="{path:localePath(`/faq/buyer`), hash: '#delivery'}"
              class="footer__nav-link"
              target="_self">
              {{ $t('footer.navigation.delivery') }}
            </nuxt-link>
          </li>
          <li class="footer__nav-list-item">
            <nuxt-link
              :to="{path:localePath(`/faq/buyer`), hash: '#return'}"
              class="footer__nav-link"
              target="_self">
              {{ $t('footer.navigation.return') }}
            </nuxt-link>
          </li>
        </ul>
      </div>
    </div>
    <div class="footer__nav-partition">
      <label class="footer__nav-title" for="about-company">{{
        $t('footer.navigation.about')
      }}</label>
      <input
        id="about-company"
        class="footer__nav-marker"
        name="tabs"
        type="checkbox"
      />
      <div class="footer__nav-list-wrapper">
        <ul class="footer__nav-list" @click="onClose">
          <li class="footer__nav-list-item">
            <old-link classes="footer__nav-link" to="/info/about-us/">{{
              $t('footer.navigation.history')
            }}</old-link>
          </li>
          <li class="footer__nav-list-item">
            <old-link classes="footer__nav-link" to="/news/">{{
              $t('footer.navigation.news')
            }}</old-link>
          </li>
          <li class="footer__nav-list-item">
            <nuxt-link
              :to="{path:localePath(`/contacts`)}"
              class="footer__nav-link">
              {{ $t('footer.navigation.contacts') }}
            </nuxt-link>
          </li>
        </ul>
      </div>
    </div>
    <div class="footer__nav-partition">
      <label class="footer__nav-title" for="to-seller">{{
        $t('footer.navigation.seller')
      }}</label>
      <input
        id="to-seller"
        class="footer__nav-marker"
        name="tabs"
        type="checkbox"
      />
      <div class="footer__nav-list-wrapper">
        <ul class="footer__nav-list" @click="onClose">
          <li class="footer__nav-list-item">
            <old-link classes="footer__nav-link" to="/stories/">{{
                $t('footer.navigation.success_stories')
              }}</old-link>
          </li>
          <li class="footer__nav-list-item">
            <old-link classes="footer__nav-link" to="/events/">{{
                $t('section.header.events')
              }}</old-link>
          </li>
          <li class="footer__nav-list-item">
            <old-link classes="footer__nav-link" to="/info/export-services/">{{
                $t('footer.navigation.export_services')
              }}</old-link>
          </li>
          <li class="footer__nav-list-item">
            <nuxt-link :to="localePath(`/faq/merchant/`)" class="footer__nav-link" target="_self">
              FAQ
            </nuxt-link>
          </li>
          <li class="footer__nav-list-item">
            <old-link classes="footer__nav-link" to="/tariffplans/">{{
                $t('footer.navigation.tariff_plans')
              }}</old-link>
          </li>
          <li class="footer__nav-list-item">
            <old-link
              classes="footer__nav-link"
              to="/info/about-tariffs-payment/"
            >{{ $t('footer.navigation.tariff_payment') }}</old-link
            >
          </li>
          <li class="footer__nav-list-item footer__nav-link"
              @click="openModalPopup"
          >{{$t("header.become_a_supplier")}}
          </li>
        </ul>
