<script>
import {ModalBus} from '@/event-bus/modal-bus';

const Cooperation = () => import('@/components/header/cooperation');

export default {
  methods: {
    openModalPopup() {
      ModalBus.$emit('open', {
        component: Cooperation,
        canCloseOnBackdrop: false
      });
    },
    onClose() {
      this.$emit('close')
    }
  },
};
</script>

<style lang="scss">
.footer__nav {
  flex-shrink: 0;
  width: 100%;
  padding-top: 26px;
  padding-bottom: 20px;

  border-bottom: 1px solid #e7e7e7;

  @media (min-width: 768px) {
    display: flex;
    justify-content: space-between;
    padding-top: 35px;
    padding-bottom: 49px;
    border-top: 1px solid #e7e7e7;
    border-bottom: none;
  }

  @media (min-width: $desktop-mid) {
    order: -1;
    width: 66.6%;
    border-top: 0;
  }
}

.footer__nav-list {
  display: none;
  margin: 0;
  padding: 0;

  list-style: none;

  @media (min-width: 768px) {
    display: block;
  }
}

.footer__nav-marker {
  position: absolute;
  z-index: -1;

  width: 1px;
  height: 1px;
  margin: -1px;
  border: 0;
  padding: 0;

  white-space: nowrap;

  clip-path: inset(100%);
  clip: rect(0 0 0 0);
  overflow: hidden;

  @media (min-width: 768px) {
    display: none;
  }
}

@media (max-width: 767px) {
  .footer__nav-marker:checked ~ .footer__nav-list-wrapper .footer__nav-list {
    display: block;
  }

  .footer__nav-list-wrapper {
    position: relative;

    &::before {
      content: "";
      position: absolute;
      top: -28px;
      right: 12px;

      width: 12px;
      height: 7px;

      background-image: url("/nimages/icons/common/arrow-down.svg");
      background-repeat: no-repeat;
    }
  }

  .footer__nav-marker:checked ~ .footer__nav-list-wrapper::before {
    transform: rotate(180deg);
  }

  .footer__nav-marker:checked ~ .footer__nav-list-wrapper {
    background-color: #f3f3f3;
    box-shadow: 0 -23px 0 23px #f3f3f3;
  }
}

.footer__nav-partition {
  margin-bottom: 26px;

  &:last-child {
    margin-bottom: 0;
  }

  @media (min-width: 768px) {
    flex-shrink: 0;
    width: 25%;
    margin-bottom: 0;
  }
}

.footer__nav-title {
  position: relative;
  z-index: 1;

  display: block;
